import { test, expect } from "@playwright/test";
// Isolated credentials only. No real client or token is generated by these browser fixtures.
for (const width of [390, 1440])
  test(`admin-only recovery setup and explicit credential copies ${width}px`, async ({
    page,
    context,
  }) => {
    await page.setViewportSize({ width, height: 900 });
    await context.grantPermissions(["clipboard-read", "clipboard-write"]);
    const callback = "https://grok.com/connectors-oauth-exchange-code/";
    let creates = 0;
    await page.route("**/api/**", async (route) => {
      const r = route.request(),
        path = new URL(r.url()).pathname;
      if (path === "/api/session")
        return route.fulfill({
          json: {
            authenticated: true,
            csrf: "fixture-csrf",
            ownerId: "340639438",
          },
        });
      if (path === "/api/saver")
        return route.fulfill({ json: { references: [], next: null } });
      if (path === "/api/collections")
        return route.fulfill({
          json: { collections: { version: 1, revision: 0, groups: [] } },
        });
      if (path === "/api/scout/status")
        return route.fulfill({
          json: {
            configured: true,
            callbackAllowlistConfigured: true,
            externalRedirects: [callback],
          },
        });
      if (path === "/api/auth/google/status")
        return route.fulfill({
          json: { configured: true, linked: true, canLink: false },
        });
      if (path === "/api/scout/clients") {
        expect(r.method()).toBe("POST");
        expect(r.headers()["x-ad-csrf"]).toBe("fixture-csrf");
        expect(r.postDataJSON()).toEqual({
          name: "A.D | Grok Scout",
          redirects: [callback],
        });
        creates++;
        return route.fulfill({
          status: 201,
          json: {
            client_id: "b08701b4-16e6-4001-a3d0-a78555878d65",
            client_secret: "fixture-not-a-real-secret",
            resource: "https://gateway.example/mcp",
            authorization_endpoint: "https://app.example/api/oauth/authorize",
            token_endpoint: "https://gateway.example/token",
          },
        });
      }
      return route.fulfill({ status: 404, json: { error: "not_found" } });
    });
    await page.goto("/#/saver?admin=1&settings=1");
    const dialog = page.getByRole("dialog");
    await expect(dialog).toBeVisible();
    await expect(page.getByLabel("URL de retour vérifiée")).toHaveValue(
      callback,
    );
    expect(creates).toBe(0);
    await page
      .getByRole("button", { name: "Créer un client Saver dédié", exact: true })
      .click();
    await expect(page.getByLabel("Client ID", { exact: true })).toHaveValue(
      "b08701b4-16e6-4001-a3d0-a78555878d65",
    );
    expect(creates).toBe(1);
    await expect(
      page.getByLabel("Client secret", { exact: true }),
    ).toHaveAttribute("type", "password");
    await page
      .getByRole("button", { name: "Copier l’ID client", exact: true })
      .click();
    expect(await page.evaluate(() => navigator.clipboard.readText())).toBe(
      "b08701b4-16e6-4001-a3d0-a78555878d65",
    );
    await page
      .getByRole("button", { name: "Copier le secret client", exact: true })
      .click();
    expect(await page.evaluate(() => navigator.clipboard.readText())).toBe(
      "fixture-not-a-real-secret",
    );
    await page
      .getByRole("button", { name: "Copier l’autorisation", exact: true })
      .click();
    expect(await page.evaluate(() => navigator.clipboard.readText())).toBe(
      "https://app.example/api/oauth/authorize",
    );
    const stored = await page.evaluate(() =>
      JSON.stringify({
        local: { ...localStorage },
        session: { ...sessionStorage },
      }),
    );
    expect(stored).not.toContain("fixture-not-a-real-secret");
    expect(page.url()).not.toContain("fixture-not-a-real-secret");
    expect(
      await page.evaluate(
        () => document.documentElement.scrollWidth <= innerWidth,
      ),
    ).toBe(true);
    await page.screenshot({ path: `artifacts/grok-setup-${width}.png` });
    await page
      .getByRole("button", { name: "Masquer les identifiants", exact: true })
      .click();
    await expect(
      page.getByRole("button", {
        name: "Copier le secret client",
        exact: true,
      }),
    ).toHaveCount(0);
  });
